//  HELPERS — funciones globales de acceso a datos
// ════════════════════════════════════════════════════════════════
function getImgPrincipal(d) {
  function _n(s) {
    if (!s || s.length < 5) return "";
    // Normalizar rutas antiguas (seguridad)
    if (s.indexOf("VEXO_WEB/Desarrollos/") === 0)
      return s.replace("VEXO_WEB/Desarrollos/", "images/Desarrollos/");
    return s;
  }
  var p = _n(d.foto_principal_url);
  if (p) return p;
  if (Array.isArray(d.imagenes) && d.imagenes.length > 0) {
    var p2 = _n(d.imagenes[0]);
    if (p2) return p2;
  }
  return d.imagen_fallback || "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=800&q=80";
}

function getDesarrolloBySlug(s) {
  return DESARROLLOS.filter(function(d) {
    return d.slug === s || d.url_slug === s;
  })[0] || null;
}

function getDesarrolloById(id) {
  return DESARROLLOS.filter(function(d) {
    return String(d.id) === String(id);
  })[0] || null;
}

function getDescargas(tipo) {
  return tipo === "brochures" ? DESCARGAS.brochures : DESCARGAS.guias;
}

